const fmtWhen = iso => { const d = new Date(iso); return isNaN(d) ? '' : `${fmtDate(d.toISOString().slice(0, 10))}, ${d.toISOString().slice(11, 16)} UTC`; };
const days = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);

// The checks again, just before posting. No vendor: stop and say so (the workflow never creates one). Same vendor and
// number already in QuickBooks: nothing is posted, unless the ledger key in its note shows an earlier approval of this
// very invoice created it (QuickBooks saved the bill but the answer never arrived); then that bill gets the PDF.
const cfg = $('Load Settings').first().json.cfg;
const ctx = { ...$input.first().json };
const inv = ctx.data.invoice;
const vendor = (ctx.qbo.results.vendor || [])[0] || null;
const bills = ctx.qbo.results.bills || [];
const until = fmtWhen(new Date(Number(ctx.link.e) * 1000).toISOString());
const release = (page, note) => [{ json: { ...ctx, route: 'release', page, releaseNote: note } }];
if (!vendor) {
  return release({ status: 409, tone: 'warn', title: 'Add the vendor first', view: ctx.view, paragraphs: [
    `QuickBooks has no active vendor named "${ctx.qbo.vendorLookupName}"${ctx.data.vendor ? ' any more (it may have been made inactive)' : ''}. The workflow never creates vendors.`,
    `Add the vendor in QuickBooks with exactly that name, or map the name in VENDOR_ALIASES, then open this link again. Nothing was posted, and the link works until ${until}.`] },
    'Approve was pressed, but the vendor is not in QuickBooks');
}
const vendorCurrency = vendor.CurrencyRef && vendor.CurrencyRef.value ? String(vendor.CurrencyRef.value).toUpperCase() : cfg.homeCurrency;
if (inv.currency !== vendorCurrency) {
  return release({ status: 409, tone: 'bad', title: 'The currency does not match', view: ctx.view, paragraphs: [
    `The invoice is in ${inv.currency}, but the vendor is set up in ${vendorCurrency} in QuickBooks. Nothing was posted. Reject it and enter it by hand.`] },
    'Approve was pressed, but the currency does not match the vendor');
}
