  currency: vendor.CurrencyRef && vendor.CurrencyRef.value ? String(vendor.CurrencyRef.value) : '' };
const marker = `[ledger:${ctx.row.key}]`;
const dup = bills.find(b => b.VendorRef && String(b.VendorRef.value) === String(vendor.Id));
if (dup && String(dup.PrivateNote || '').includes(marker)) {
  return [{ json: { ...ctx, vendor: vendorInfo, route: 'adopt', existingBill: { Id: String(dup.Id), DocNumber: dup.DocNumber || '', TotalAmt: dup.TotalAmt } } }];
}
if (dup) return [{ json: { ...ctx, vendor: vendorInfo, route: 'duplicate', duplicate: { Id: String(dup.Id), DocNumber: dup.DocNumber || inv.invoiceNumber, TxnDate: dup.TxnDate || '', TotalAmt: dup.TotalAmt } } }];
return [{ json: { ...ctx, vendor: vendorInfo, route: 'post' } }];

// Finds the same PDF in the email again. Gmail issues a new attachment ID every time a message is read, so the ID
// from the first run is not reused. The part ID never changes, so it finds the PDF even when the PDF has no filename
// (it was saved as "invoice.pdf").
const ctx = $('Approval Checks').first().json;
const want = ctx.data.pdf || {};
const parts = [];
const walk = p => { if (!p) return; if (p.body && p.body.attachmentId) parts.push(p); (p.parts || []).forEach(walk); };
walk($input.first().json.payload);
const name = p => String(p.filename || '');
const isPdf = p => { const m = String(p.mimeType || '').toLowerCase(); return m === 'application/pdf' || (/\.pdf$/i.test(name(p)) && (m === 'application/octet-stream' || m === '')); };
