const hit = parts.find(p => String(p.partId) === String(want.partId) && isPdf(p) && name(p) === wantName)
  || (wantName ? parts.find(p => isPdf(p) && name(p) === wantName) : null);
if (!hit) return [{ json: { ...ctx, route: 'release', releaseReason: 'missing-pdf' } }];
return [{ json: { ...ctx, route: 'download', attachmentId: String(hit.body.attachmentId) } }];

// The Bill: each invoice line becomes an account based expense line on QBO_EXPENSE_ACCOUNT_ID, and the tax becomes
// one more line on QBO_TAX_ACCOUNT_ID, so the bill total matches lines plus tax. CurrencyRef is the vendor's own
// currency, which the checks above matched to the invoice; QuickBooks requires it when multicurrency is on. The request ID (one per approval attempt) makes retries safe: QuickBooks answers a repeated ID with the
// first result.
const cfg = $('Load Settings').first().json.cfg;
const ctx = $('Approval Checks').first().json;
const attempt = Number($input.first().json._attempt) || 1;
const inv = ctx.data.invoice, d = ctx.data;
const r2 = v => Math.round(Number(v) * 100) / 100;
const Line = inv.lines.map(l => ({
  DetailType: 'AccountBasedExpenseLineDetail',
  Amount: r2(l.amount),
  Description: (l.description || 'Invoice line').slice(0, 4000),
  AccountBasedExpenseLineDetail: { AccountRef: { value: cfg.expenseAccountId } },
}));
if (Number(d.tax) > 0) {
  Line.push({ DetailType: 'AccountBasedExpenseLineDetail', Amount: r2(d.tax), Description: `Tax on invoice ${inv.invoiceNumber}`,
    AccountBasedExpenseLineDetail: { AccountRef: { value: cfg.taxAccountId } } });
}
const shown = (d.problems || []).filter(p => p.level !== 'block').map(p => p.text);
const marker = ` [ledger:${ctx.row.key}]`;
const note = `Entered from email by the invoice approval workflow. Approved by ${ctx.name} on ${new Date().toISOString().slice(0, 10)}.`
  + (shown.length ? ` Shown at approval: ${shown.join('; ')}.` : '');
const bill = { VendorRef: { value: ctx.vendor.id }, TxnDate: inv.invoiceDate, DocNumber: inv.invoiceNumber, PrivateNote: note.slice(0, 4000 - marker.length) + marker, Line };
if (d.dueDate) bill.DueDate = d.dueDate;
if (ctx.vendor.currency) bill.CurrencyRef = { value: ctx.vendor.currency };
return [{ json: { ...ctx, _attempt: attempt, bill, requestId: `bill-${ctx.row.key}-${ctx.claimId}`.slice(0, 50) } }];

// n8n error objects (from an error output) carry message, description and sometimes httpCode
const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e.slice(0, 400);
  const parts = [e.httpCode, e.message, e.description].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(String);
  return [...new Set(parts)].join(' - ').replace(/\s+/g, ' ').slice(0, 400);
};

// Turns one QuickBooks answer (HTTP node with "never error" and the full response) into ok, retry or fail.
// Intuit reports errors as { Fault: { Error: [{ Message, Detail, code }], type } }.
const qboOutcome = res => {
  if (res.error && !res.statusCode) {
    const m = errText(res.error);
    const auth = /refresh token|oauth|invalid_grant|unauthori[sz]ed|\b401\b/i.test(m);
    return { ok: false, status: 0, kind: auth ? 'auth' : 'unavailable', code: '', message: m, tid: '', retryable: !auth, retryAfter: 0 };
  }
  const status = Number(res.statusCode) || 0;
  let body = res.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
  const obj = body && typeof body === 'object' ? body : null;
  const fault = obj ? (obj.Fault || obj.fault || (obj.QueryResponse && obj.QueryResponse.Fault)) : null;
  if (status >= 200 && status < 300 && obj && !fault) return { ok: true, status, body: obj };
  const errs = fault ? (fault.Error || fault.error || []) : [];
  const first = errs[0] || {};
  const text = [first.Message || first.message, first.Detail || first.detail].filter(Boolean).join(': ')
    || (obj ? (obj.detail || obj.message || '') : String(res.body || '').slice(0, 200));
  const code = String(first.code || (obj && obj.code) || '');
  const kind = status === 401 ? 'auth' : status === 403 ? 'permission' : status === 429 ? 'throttled'
    : (status >= 500 || status === 0) ? 'unavailable' : 'request';
  const ra = Number((res.headers || {})['retry-after']);
  return { ok: false, status, kind, code, message: String(text).replace(/\s+/g, ' ').slice(0, 300), tid: (res.headers || {}).intuit_tid || '',
    retryable: kind === 'throttled' || kind === 'unavailable', retryAfter: Number.isFinite(ra) && ra > 0 ? ra : 0 };
};
// Intuit asks apps to wait 60 seconds after a 429. Server errors and dropped connections back off exponentially.
const qboWait = (o, attempt, cfg) => o.kind === 'throttled' ? Math.min(120, o.retryAfter || cfg.qboRateLimitWait) : Math.min(60, cfg.retryBaseSeconds * 2 ** (attempt - 1));
const qboExplain = (o, tries) => ({
  auth: `QuickBooks refused the connection (401${o.code ? ', code ' + o.code : ''}). The QuickBooks credential in n8n has expired or was disconnected, so open it in n8n and reconnect it`,
  permission: `QuickBooks refused access (403${o.code ? ', code ' + o.code : ''}). The connected user must be a QuickBooks admin, and QBO_REALM_ID must be the company that credential is connected to`,
  throttled: `QuickBooks still answered 429 (rate limit) after ${tries} tries`,
  unavailable: `QuickBooks did not answer${o.status ? ' (' + o.status + ')' : ''} after ${tries} tries`,
  request: `QuickBooks rejected the request (${o.status}${o.code ? ', code ' + o.code : ''})`,
}[o.kind] || `QuickBooks error ${o.status}`) + (o.message ? `. It said: ${o.message}` : '') + (o.tid ? ` (intuit_tid ${o.tid})` : '');
const sleep = s => new Promise(r => setTimeout(r, s * 1000));

// Reads the answer to the bill create: retry with backoff, or stop with a clear reason.
const cfg = $('Load Settings').first().json.cfg;
const ctx = { ...$('Build Bill').first().json };
const attempt = Number(ctx._attempt) || 1;
const o = qboOutcome($input.first().json);
if (o.ok && o.body.Bill && o.body.Bill.Id) {
  return [{ json: { ...ctx, route: 'created', createdBill: { Id: String(o.body.Bill.Id), DocNumber: o.body.Bill.DocNumber || '', TotalAmt: o.body.Bill.TotalAmt } } }];
}
if (!o.ok && o.retryable && attempt < cfg.apiMaxAttempts) {
  await sleep(qboWait(o, attempt, cfg));
  return [{ json: { ...ctx, _attempt: attempt + 1, route: 'again' } }];
}
return [{ json: { ...ctx, route: 'failed', billError: { kind: o.kind || 'request', text: o.ok ? 'QuickBooks answered without a bill' : qboExplain(o, attempt), unknown: !o.ok && o.retryable } } }];

// The two parts of QuickBooks' Attachable upload (one multipart request, as in Intuit's guide): file_metadata_01 is
// the Attachable JSON that links the file to the bill (application/json, named attachment.json) and file_content_01
// is the PDF itself. Both are n8n binary parts, so the HTTP node sends them with their own content types.
const ctx = $('Approval Checks').first().json;
const attempt = Number($input.first().json._attempt) || 1;
const created = $('Check Bill Reply').isExecuted ? $('Check Bill Reply').first().json.createdBill : null;
const bill = created || ctx.existingBill;
let b64 = String($('Gmail: Download PDF').first().json.data || '').replace(/-/g, '+').replace(/_/g, '/').replace(/\s+/g, '');
while (b64.length % 4) b64 += '=';
const fileName = (String((ctx.data.pdf || {}).filename || 'invoice.pdf').replace(/\.pdf$/i, '').replace(/[^A-Za-z0-9 ._()-]/g, '_').slice(0, 90) || 'invoice') + '.pdf';
const meta = { AttachableRef: [{ EntityRef: { type: 'Bill', value: String(bill.Id) }, IncludeOnSend: false }], FileName: fileName, ContentType: 'application/pdf' };
const metaJson = JSON.stringify(meta);
const metaB64 = typeof Buffer !== 'undefined' ? Buffer.from(metaJson, 'utf8').toString('base64') : btoa(metaJson);
return [{
  json: { ...ctx, _attempt: attempt, attachBill: bill, adopted: !created, fileName, requestId: `att-${ctx.row.key}-${ctx.claimId}`.slice(0, 50) },
  binary: {
    meta: { data: metaB64, mimeType: 'application/json', fileName: 'attachment.json' },
    pdf: { data: b64, mimeType: 'application/pdf', fileName },
  },
}];

