}[o.kind] || `QuickBooks error ${o.status}`) + (o.message ? `. It said: ${o.message}` : '') + (o.tid ? ` (intuit_tid ${o.tid})` : '');
const sleep = s => new Promise(r => setTimeout(r, s * 1000));

// Reads the upload answer. The bill exists either way, so a failed upload does not undo the approval: the page, the
// log and an alert say to attach the PDF by hand.
const cfg = $('Load Settings').first().json.cfg;
const ctx = { ...$('Build Attachment').first().json };
const attempt = Number(ctx._attempt) || 1;
const o = qboOutcome($input.first().json);
if (o.ok) {
  const first = (o.body.AttachableResponse || [])[0] || {};
  if (first.Attachable && first.Attachable.Id) return [{ json: { ...ctx, route: 'done', attachableId: String(first.Attachable.Id), attachError: '' } }];
  const f = first.Fault && ((first.Fault.Error || [])[0] || {});
  return [{ json: { ...ctx, route: 'done', attachError: f ? `QuickBooks refused the file (code ${f.code}): ${[f.Message, f.Detail].filter(Boolean).join(': ')}` : 'QuickBooks answered without an attachment' } }];
}
