// n8n error objects (from an error output) carry message, description and sometimes httpCode
const errText = e => {
  if (!e) return '';
  if (typeof e === 'string') return e.slice(0, 400);
  const parts = [e.httpCode, e.message, e.description].filter(v => v !== undefined && v !== null && String(v).trim() !== '').map(String);
  return [...new Set(parts)].join(' - ').replace(/\s+/g, ' ').slice(0, 400);
};

const cents = v => Math.round(Number(v) * 100);
const money = v => {
  const c = Math.round(Number(v) * 100), a = Math.abs(c);
  return (c < 0 ? '-' : '') + String(Math.floor(a / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '.' + String(a % 100).padStart(2, '0');
};
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const isDate = s => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const d = new Date(s + 'T00:00:00Z');
  return !isNaN(d) && d.toISOString().slice(0, 10) === s;
};
const fmtDate = s => isDate(s) ? `${MONTHS[Number(s.slice(5, 7)) - 1]} ${Number(s.slice(8, 10))}, ${s.slice(0, 4)}` : (s || 'not printed');
const fmtWhen = iso => { const d = new Date(iso); return isNaN(d) ? '' : `${fmtDate(d.toISOString().slice(0, 10))}, ${d.toISOString().slice(11, 16)} UTC`; };
const days = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);

// The approval stopped before a bill was posted (or QuickBooks did not confirm it). The ledger row goes back to
// awaiting_approval in the next node, so the same link works again once the problem is fixed.
const base = $('Check Invoice State').first().json;
const x = $input.first().json;
const view = base.view;
const label = `${view.vendor} invoice ${view.number}`;
const until = fmtWhen(new Date(Number(base.link.e) * 1000).toISOString());
const nothing = `Nothing was posted. The invoice is waiting for approval again, and this link works until ${until}.`;
let page, note, failRun = '';
if (x.error) {
  page = { status: 503, tone: 'bad', title: 'Gmail did not return the PDF', view, paragraphs: [`The original email could not be loaded (${errText(x.error)}).`, nothing, 'Try again in a few minutes.'] };
  note = 'Approval stopped: Gmail did not return the PDF';
  failRun = `Approving ${label} stopped: Gmail did not return the original email or PDF (${errText(x.error)}).`;
} else if (x.route === 'release' && x.page) {
  page = x.page; note = x.releaseNote;
} else if (x.route === 'approval-failed') {
  page = { status: 503, tone: 'bad', title: 'QuickBooks did not answer', view, paragraphs: [`${x.qboError.text}.`, nothing, 'Try again in a few minutes.'] };
  note = `Approval stopped: ${x.qboError.text}`;
  failRun = `Approving ${label} stopped before anything was posted: ${x.qboError.text}.`;
} else if (x.route === 'release' && x.releaseReason === 'missing-pdf') {
  page = { status: 409, tone: 'bad', title: 'The PDF is gone', view, paragraphs: [`The original email or its PDF is no longer in Gmail, so it cannot be attached to the bill.`, nothing] };
  note = 'Approval stopped: the PDF is no longer in Gmail';
  failRun = `Approving ${label} stopped: the email or its PDF was deleted from Gmail.`;
} else if (x.route === 'failed') {
  page = { status: 502, tone: 'bad', title: 'QuickBooks did not accept the bill', view, paragraphs: [`${x.billError.text}.`, x.billError.unknown
    ? `QuickBooks may still have saved it. Open this link again in a few minutes: if the bill is there, it gets the PDF and no second bill is created. ${nothing}`
    : nothing] };
  note = x.billError.unknown ? `Approval stopped and QuickBooks may have saved the bill (its answer was lost): ${x.billError.text}` : `Approval stopped: ${x.billError.text}`;
  failRun = x.billError.unknown ? `The bill for ${label} was not confirmed: ${x.billError.text}. QuickBooks may have saved it; approving again finds it.` : `The bill for ${label} was not created: ${x.billError.text}.`;
} else {
  page = { status: 500, tone: 'bad', title: 'Something went wrong', view, paragraphs: [nothing] };
  note = 'Approval stopped'; failRun = `Approving ${label} stopped on an unexpected path.`;
}
return [{ json: { ...base, page, releaseNote: String(note).slice(0, 1000), failRun } }];

// The final ledger update for this decision. It only applies while the row is still in the state this path started
// from (awaiting_approval for a reject, approving for an approval), so a decision can never be recorded twice.
const x = $input.first().json;
const base = $('Check Invoice State').first().json;
let decision, flow;
if (x.route === 'reject') {
  flow = 'reject';
  decision = { status: 'rejected', expect: 'awaiting_approval', billId: '', note: `Rejected by ${base.name}: ${base.reason || 'no reason given'}` };
} else if (x.route === 'duplicate') {
  flow = 'duplicate';
  decision = { status: 'duplicate', expect: 'approving', billId: x.duplicate.Id, note: `Already in QuickBooks as bill ${x.duplicate.DocNumber} (Id ${x.duplicate.Id}), so nothing was posted` };
} else {
  flow = 'posted';
  decision = { status: 'posted', expect: 'approving', billId: String(x.attachBill.Id),
    note: (x.adopted ? `Bill Id ${x.attachBill.Id} was already saved by an earlier approval` : `Posted as bill Id ${x.attachBill.Id}`)
      + (x.attachError ? `. The PDF was NOT attached: ${x.attachError}` : ' with the PDF attached') };
}
return [{ json: { ...base, flow, decision, bill: x.attachBill || null, adopted: !!x.adopted, attachError: x.attachError || '', duplicate: x.duplicate || null } }];

