const label = `${p.view.vendor} invoice ${p.view.number}`;
const page = pg => [{ json: { ...p, route: 'page', page: pg } }];
if (r.error || !r.key) {
  const why = r.error ? errText(r.error) : 'the row was no longer in the expected state';
  if (p.flow === 'posted') {
    return page({ status: 500, tone: 'bad', title: 'Posted, but not recorded', paragraphs: [`${label} is in QuickBooks as bill Id ${p.decision.billId}, but the ledger could not be updated. Do not approve it again.`],
      failRun: `Bill Id ${p.decision.billId} was created for ${p.row.key}, but the ledger update failed (${why}). Set that ledger row to posted by hand.` });
  }
  if (r.error) {
    return page({ status: 500, tone: 'bad', title: 'Something went wrong', paragraphs: ['Your choice could not be recorded, so nothing was changed. Try the link again in a few minutes.'],
      failRun: `The ${p.flow} decision for ${p.row.key} could not be saved in the ledger (${why}).` });
  }
