};

// The Gmail label an email should carry, worked out from the ledger rows of all its PDFs
const LABEL_KEYS = ['toProcess', 'awaiting', 'processed', 'rejected', 'needsReview'];
const pickLabel = rows => {
  const st = rows.map(r => r.status);
  if (!st.length) return null;
  // Every PDF needs its own row before the email leaves To Process: a PDF of the same email may still be read right now
  const expected = Math.max(0, ...rows.map(r => { try { return Number(JSON.parse(r.data || '{}').pdfCount) || 0; } catch (e) { return 0; } }));
  if (expected && rows.filter(r => !/-0$/.test(String(r.key))).length < expected) return 'toProcess';
  if (st.includes('retry')) return 'toProcess';                  // tried again on the next run
  // An approval request Slack never confirmed (Slack down, or n8n stopped in between): the next run sends it again
  if (rows.some(r => r.status === 'awaiting_approval' && !r.notifiedAt)) return 'toProcess';
  if (st.some(s => s === 'awaiting_approval' || s === 'approving')) return 'awaiting';
  if (st.includes('needs_review')) return 'needsReview';
  if (st.some(s => s === 'posted' || s === 'duplicate')) return 'processed';
  if (st.every(s => s === 'rejected')) return 'rejected';
