const relabelFor = (target, ids, current) => {
  const add = target ? [ids[target]].filter(Boolean) : [];
  const remove = target ? LABEL_KEYS.filter(k => k !== target).map(k => ids[k]).filter(Boolean) : [];
  // Skip the call when the email already has exactly that label (the current labels are known during intake only)
  const settled = Array.isArray(current) && add.every(l => current.includes(l)) && !remove.some(l => current.includes(l));
  return { needed: !!target && add.length > 0 && !settled, target, add, remove };
};

// Moves the email out of Awaiting Approval once none of its PDFs is waiting any more.
const p = $('Check Decision Saved').first().json;
const rows = $input.all().map(i => i.json);
if (rows[0] && rows[0].error) return [{ json: { ...p, relabel: { needed: false, target: null, lookupError: errText(rows[0].error) } } }];
const target = pickLabel(rows.filter(r => r && r.key));
return [{ json: { ...p, relabel: { ...relabelFor(target, p.data.labelIds || {}), messageId: p.row.messageId } } }];

