    paragraphs: [`${label} is bill Id ${p.decision.billId} in QuickBooks${p.attachError ? '' : ', with the PDF attached'}. Approved by ${p.name}.`, ...warnings] };
  text = `:white_check_mark: *Posted to QuickBooks*: ${se(label)}, ${se(v.currency)} ${money(v.billTotal)}. Bill Id ${se(p.decision.billId)}, approved by ${se(p.name)}.`;
