    paragraphs: [`${label} was not posted: QuickBooks already has bill ${p.duplicate.DocNumber} from this vendor (Id ${p.duplicate.Id}), probably entered by hand.`, ...warnings] };
  text = `:repeat: *Not posted, already in QuickBooks*: ${se(label)} is bill Id ${se(p.duplicate.Id)}. ${se(p.name)} pressed Approve, and nothing was posted twice.`;
