  event = 'Rejected';
  page = { status: 200, tone: warnings.length ? 'warn' : 'ok', title: 'Rejected', paragraphs: [`${label} was rejected by ${p.name}. Nothing was posted.`, `Reason: ${p.reason || 'no reason given'}.`, ...warnings] };
  text = `:x: *Invoice rejected*: ${se(label)}, by ${se(p.name)}. Reason: ${se(p.reason || 'none given')}.`;
}
if (warnings.length) text += `\n:warning: ${warnings.map(se).join(' ')}`;
const sheetRow = [new Date().toISOString(), event, p.decision.status, v.vendor, v.number, v.invoiceDate, v.dueDate, v.currency, v.total === null ? '' : v.total,
  v.problems.join('; '), p.decision.billId, p.name, [p.decision.note, ...warnings].join(' '), v.from, v.subject, p.row.key];
const failRun = warnings.length ? `${label} was ${p.flow === 'reject' ? 'rejected' : p.flow === 'posted' ? 'posted' : 'handled'}, but: ${warnings.join(' ')}` : '';
return [{ json: { ...p, page: { ...page, failRun }, slack: { text }, sheetRow, logToSheet: !!cfg.sheetId } }];

