const cfg = $('Load Settings').first().json.cfg;
const x = $input.first().json;
let p;
if ($('Explain Release').isExecuted) {
  const r = $('Explain Release').first().json;
  p = { ...r.page, paragraphs: [...(r.page.paragraphs || [])], failRun: r.failRun || '' };
  if (x.error || !x.key) {
    p.paragraphs.push('Note: the invoice could not be set back to waiting for approval. The team has been told.');
    p.failRun = [p.failRun, `The ledger row ${r.row.key} is still marked approving (${x.error ? errText(x.error) : 'it was not in that state'}). Set it back to awaiting_approval by hand so its links work again.`].filter(Boolean).join(' ');
  }
} else p = x.page;
if (!p) p = { status: 500, tone: 'bad', title: 'Something went wrong', paragraphs: ['Nothing was changed.'], failRun: 'The approval page had nothing to show (unexpected path).' };
const h = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const amount = v => v === null || v === undefined || v === '' ? '?' : money(v);
const viewHtml = v => {
  if (!v) return '';
  const rows = (v.lines || []).map(l => `<tr><td>${h(l.d || 'Line')}</td><td class="n">${amount(l.a)}</td></tr>`).join('');
  const tax = Number(v.tax) > 0 ? `<tr><td>Tax</td><td class="n">${money(v.tax)}</td></tr>` : '';
  const total = v.billTotal !== null && v.billTotal !== undefined ? `<tr class="t"><td>Bill total</td><td class="n">${h(v.currency)} ${money(v.billTotal)}</td></tr>` : '';
  const printed = v.total !== null && v.total !== undefined && v.billTotal !== null && v.billTotal !== undefined && Math.abs(v.total - v.billTotal) > 0.009
    ? `<tr><td>Total printed on the invoice</td><td class="n">${h(v.currency)} ${money(v.total)}</td></tr>` : '';
  const problems = v.problems && v.problems.length ? `<h2>Problems</h2><ul>${v.problems.map(t => `<li>${h(t)}</li>`).join('')}</ul>` : '<p class="muted">All checks passed.</p>';
  return `<dl><dt>Vendor</dt><dd>${h(v.vendor)}</dd><dt>Invoice</dt><dd>${h(v.number)}</dd><dt>Dated</dt><dd>${h(fmtDate(v.invoiceDate))}</dd>`
    + `<dt>Due</dt><dd>${v.dueDate ? h(fmtDate(v.dueDate)) : 'By the vendor&#39;s payment terms'}</dd><dt>QuickBooks vendor</dt><dd>${h(v.qboVendor)}</dd>`
